/* M3: differential testing against Unicorn, a reference ARM CPU.
 *
 * Linked with any program generated by `python -m recomp --trace`. For
 * every recompiled function and many random inputs:
 *   1. Unicorn runs the original ARM code (the same bytes, from the
 *      program image) and records the CPU state before every
 *      instruction, plus every memory write.
 *   2. The recompiled code runs on identical registers and memory; each
 *      RECOMP_TRACE / write hook is compared with Unicorn's next step.
 * The first difference is reported with the instruction that caused it.
 *
 * Usage: <prog>_diff [runs-per-function] [skip,list | +only,list]
 *
 * Functions that take function pointers (or pointers to structs holding
 * them) are skipped: random inputs would make them call random addresses.
 */
#include <inttypes.h>
#include <setjmp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unicorn/unicorn.h>

#include "context.h"

#define STACK_TOP     0x10000000u
#define STACK_WINDOW  0x10000u              /* synced below STACK_TOP each run */
#define RETURN_ADDR   0x00ABC000u           /* sentinel lr: "returned to the harness" */
#define SCRATCH       0x08000000u           /* random data for pointer arguments */
#define SCRATCH_SIZE  0x1000u
#define LIMIT         20000                 /* instructions per run (loops can be long) */

typedef struct {
    uint32_t addr;
    uint32_t r[15];             /* r0..r14 */
    uint32_t nzcv;
    uint64_t d[16];             /* VFP d0-d15 (= s0-s31) */
    uint32_t fp_nzcv;           /* FPSCR compare flags */
    size_t   writes_before;     /* writes made by earlier instructions */
} Step;

typedef struct { uint32_t addr, size; uint64_t value; } Write;

/* Unicorn's run: the reference trace. */
static Step  *ref;
static size_t ref_len, ref_cap;
static Write *ref_writes;
static size_t ref_nwrites, ref_wcap;

/* Our run, compared against it as it happens. */
static jmp_buf stop;
static size_t step, nwrites;
static const char *prev_text;
static uint32_t prev_addr;
static const char *cur_fn;
static int cur_run;

enum { STOP_LIMIT = 1, STOP_DIVERGED = 2 };

static uc_engine *uc;
static uint8_t *mem;

static uint32_t rng_state = 0xC0FFEE11u;
static uint32_t rnd(void)
{
    uint32_t x = rng_state;
    x ^= x << 13; x ^= x >> 17; x ^= x << 5;
    return rng_state = x;
}

static void check_uc(uc_err e, const char *what)
{
    if (e != UC_ERR_OK) {
        fprintf(stderr, "unicorn: %s: %s\n", what, uc_strerror(e));
        exit(2);
    }
}

/* ---------------------------------------------------------------- Unicorn side */

static const int uc_regs[15] = {
    UC_ARM_REG_R0, UC_ARM_REG_R1, UC_ARM_REG_R2, UC_ARM_REG_R3, UC_ARM_REG_R4,
    UC_ARM_REG_R5, UC_ARM_REG_R6, UC_ARM_REG_R7, UC_ARM_REG_R8, UC_ARM_REG_R9,
    UC_ARM_REG_R10, UC_ARM_REG_R11, UC_ARM_REG_R12, UC_ARM_REG_SP, UC_ARM_REG_LR,
};

static int uc_dregs[16];

static void read_uc_state(uint32_t *r, uint32_t *nzcv, uint64_t *d, uint32_t *fp_nzcv)
{
    void *ptrs[16];
    for (int i = 0; i < 15; i++)
        ptrs[i] = &r[i];
    uc_reg_read_batch(uc, (int *)uc_regs, ptrs, 15);
    uint32_t cpsr, fpscr;
    uc_reg_read(uc, UC_ARM_REG_CPSR, &cpsr);
    *nzcv = cpsr >> 28;
    for (int i = 0; i < 16; i++)
        ptrs[i] = &d[i];
    uc_reg_read_batch(uc, uc_dregs, ptrs, 16);
    uc_reg_read(uc, UC_ARM_REG_FPSCR, &fpscr);
    *fp_nzcv = fpscr >> 28;
}

static void on_code(uc_engine *u, uint64_t addr, uint32_t size, void *user)
{
    (void)u; (void)size; (void)user;
    if (ref_len == ref_cap) {
        ref_cap = ref_cap ? 2 * ref_cap : 4096;
        ref = realloc(ref, ref_cap * sizeof *ref);
    }
    Step *s = &ref[ref_len++];
    s->addr = (uint32_t)addr;
    s->writes_before = ref_nwrites;
    read_uc_state(s->r, &s->nzcv, s->d, &s->fp_nzcv);
}

static bool on_write(uc_engine *u, uc_mem_type type, uint64_t addr, int size, int64_t value, void *user)
{
    (void)u; (void)type; (void)user;
    if (ref_nwrites == ref_wcap) {
        ref_wcap = ref_wcap ? 2 * ref_wcap : 4096;
        ref_writes = realloc(ref_writes, ref_wcap * sizeof *ref_writes);
    }
    uint64_t mask = size >= 8 ? ~0ull : (1ull << (8 * size)) - 1;
    ref_writes[ref_nwrites++] = (Write){ (uint32_t)addr, (uint32_t)size, (uint64_t)value & mask };
    return true;
}

typedef enum { UC_RETURNED, UC_LIMIT, UC_FAULT } UcEnd;

static UcEnd run_unicorn(uint32_t entry, const uint32_t *r, uint32_t nzcv, const uint64_t *d, uint32_t fpscr,
                         Step *fin)
{
    for (int i = 0; i < 15; i++)
        check_uc(uc_reg_write(uc, uc_regs[i], &r[i]), "reg write");
    for (int i = 0; i < 16; i++)
        check_uc(uc_reg_write(uc, uc_dregs[i], &d[i]), "vfp reg write");
    check_uc(uc_reg_write(uc, UC_ARM_REG_FPSCR, &fpscr), "fpscr write");
    uint32_t cpsr;
    uc_reg_read(uc, UC_ARM_REG_CPSR, &cpsr);
    cpsr = (cpsr & 0x0FFFFFFFu & ~0x20u) | (nzcv << 28);      /* flags; ARM (not Thumb) state */
    uc_reg_write(uc, UC_ARM_REG_CPSR, &cpsr);

    ref_len = ref_nwrites = 0;
    uc_err e = uc_emu_start(uc, entry, RETURN_ADDR, 0, LIMIT);
    read_uc_state(fin->r, &fin->nzcv, fin->d, &fin->fp_nzcv);
    uint32_t pc;
    uc_reg_read(uc, UC_ARM_REG_PC, &pc);
    if (e != UC_ERR_OK)
        return UC_FAULT;
    return pc == RETURN_ADDR ? UC_RETURNED : UC_LIMIT;
}

/* ---------------------------------------------------------------- our side */

static void report_header(void)
{
    printf("DIVERGENCE in %s (run %d, step %zu)\n", cur_fn, cur_run, step);
    if (!prev_text) {
        printf("  at function entry\n");
        return;
    }
    printf("  after %08" PRIx32 " `%s`\n", prev_addr, prev_text);
    const Step *s = &ref[step - 1];     /* both sides agreed on this state */
    printf("  registers before it:");
    for (int i = 0; i < 15; i++)
        printf("%s %08" PRIx32, i == 8 ? "\n                      " : "", s->r[i]);
    printf("\n");
}

static void report_state(const Ctx *ctx, const Step *s)
{
    static const char *names[15] = { "r0", "r1", "r2", "r3", "r4", "r5", "r6", "r7",
                                     "r8", "r9", "r10", "r11", "r12", "sp", "lr" };
    for (int i = 0; i < 15; i++)
        if (ctx->r[i] != s->r[i])
            printf("    %-3s recompiled 0x%08" PRIx32 "  unicorn 0x%08" PRIx32 "\n", names[i], ctx->r[i], s->r[i]);
    const char flag[4] = { 'n', 'z', 'c', 'v' };
    uint32_t ours[4] = { ctx->n, ctx->z, ctx->c, ctx->v };
    for (int i = 0; i < 4; i++) {
        uint32_t theirs = (s->nzcv >> (3 - i)) & 1;
        if (ours[i] != theirs)
            printf("    %c   recompiled %" PRIu32 "  unicorn %" PRIu32 "\n", flag[i], ours[i], theirs);
    }
    for (int i = 0; i < 16; i++)
        if (ctx->vfp.x[i] != s->d[i])
            printf("    d%-2d recompiled 0x%016" PRIx64 "  unicorn 0x%016" PRIx64 "  (s%d/s%d)\n",
                   i, ctx->vfp.x[i], s->d[i], 2 * i, 2 * i + 1);
    if (ctx->fpscr >> 28 != s->fp_nzcv)
        printf("    fpscr nzcv recompiled %" PRIx32 "  unicorn %" PRIx32 "\n", ctx->fpscr >> 28, s->fp_nzcv);
}

static int same_state(const Ctx *ctx, const Step *s)
{
    for (int i = 0; i < 15; i++)
        if (ctx->r[i] != s->r[i])
            return 0;
    for (int i = 0; i < 16; i++)
        if (ctx->vfp.x[i] != s->d[i])
            return 0;
    uint32_t nzcv = s->nzcv;
    return ctx->n == ((nzcv >> 3) & 1) && ctx->z == ((nzcv >> 2) & 1)
        && ctx->c == ((nzcv >> 1) & 1) && ctx->v == (nzcv & 1)
        && ctx->fpscr >> 28 == s->fp_nzcv;
}

static void check_writes_done(void)
{
    size_t expected = step < ref_len ? ref[step].writes_before : ref_nwrites;
    if (nwrites < expected) {
        report_header();
        const Write *w = &ref_writes[nwrites];
        printf("    missing write: unicorn wrote [0x%08" PRIx32 "] = 0x%" PRIx64 " (%" PRIu32 " bytes)\n",
               w->addr, w->value, w->size);
        longjmp(stop, STOP_DIVERGED);
    }
}

void recomp_trace(Ctx *ctx, uint32_t addr, const char *text)
{
    check_writes_done();
    if (step == ref_len)
        longjmp(stop, STOP_LIMIT);      /* Unicorn stopped here; compared everything it ran */

    const Step *s = &ref[step];
    if (addr != s->addr || !same_state(ctx, s)) {
        report_header();
        if (addr != s->addr)
            printf("    next instruction: recompiled %08" PRIx32 " `%s`, unicorn %08" PRIx32 "\n", addr, text, s->addr);
        report_state(ctx, s);
        longjmp(stop, STOP_DIVERGED);
    }
    prev_addr = addr;
    prev_text = text;
    step++;
}

void recomp_trace_write(uint32_t addr, uint32_t size, uint64_t value)
{
    size_t limit = step < ref_len ? ref[step].writes_before : ref_nwrites;
    const Write *w = nwrites < limit ? &ref_writes[nwrites] : NULL;
    if (!w || w->addr != addr || w->size != size || w->value != value) {
        report_header();
        printf("    recompiled wrote [0x%08" PRIx32 "] = 0x%" PRIx64 " (%" PRIu32 " bytes)\n", addr, value, size);
        if (w)
            printf("    unicorn    wrote [0x%08" PRIx32 "] = 0x%" PRIx64 " (%" PRIu32 " bytes)\n", w->addr, w->value, w->size);
        else
            printf("    unicorn made no such write\n");
        longjmp(stop, STOP_DIVERGED);
    }
    nwrites++;
}

/* ---------------------------------------------------------------- setup */

/* Bring both memories to the same starting point: fresh image, random
   scratch data, zeroed stack window. Writes from earlier runs elsewhere
   are identical on both sides (or we'd have stopped). */
static void sync_memory(void)
{
    recomp_load_image(mem);
    for (uint32_t i = 0; i < SCRATCH_SIZE; i++)
        mem[SCRATCH + i] = (uint8_t)rnd();
    memset(mem + STACK_TOP - STACK_WINDOW, 0, STACK_WINDOW);

    for (const RecompSegment *s = recomp_segments; s->size; s++)
        check_uc(uc_mem_write(uc, s->addr, mem + s->addr, s->size), "sync image");
    check_uc(uc_mem_write(uc, SCRATCH, mem + SCRATCH, SCRATCH_SIZE), "sync scratch");
    check_uc(uc_mem_write(uc, STACK_TOP - STACK_WINDOW, mem + STACK_TOP - STACK_WINDOW, STACK_WINDOW), "sync stack");
}

/* Argument registers: edge values, random words, or aligned scratch pointers. */
static uint32_t random_arg(void)
{
    static const uint32_t edges[] = { 0, 1, 2, 3, 5, 0x7FFFFFFF, 0x80000000, 0xFFFFFFFF, 0xFFFFFFFE, 100 };
    switch (rnd() % 3) {
    case 0:  return edges[rnd() % (sizeof edges / sizeof edges[0])];
    case 1:  return rnd();
    default: return SCRATCH + 4 * (rnd() % (SCRATCH_SIZE / 8));
    }
}

/* VFP register contents: special values (NaNs incl. signalling ones,
   infinities, denormals, signed zeros, values near the int32 limits) as
   float pairs or doubles, ordinary doubles, or random bits. */
static uint64_t random_vfp(void)
{
    static const uint32_t fs[] = { 0x00000000, 0x80000000, 0x3F800000, 0xBF800000, 0x3FC00000, 0x7F800000,
                                   0xFF800000, 0x7FC00000, 0xFFC12345, 0x7F812345, 0x00000001, 0x80400000,
                                   0x7F7FFFFF, 0x4F000000, 0xCF000001, 0x4F800000 };
    static const uint64_t ds[] = { 0x0000000000000000ull, 0x8000000000000000ull, 0x3FF0000000000000ull,
                                   0xC00A000000000000ull, 0x7FF0000000000000ull, 0xFFF0000000000000ull,
                                   0x7FF8000000000000ull, 0x7FF4000000000123ull, 0x0000000000000001ull,
                                   0x41E0000000000000ull, 0xC1E0000000200000ull, 0x41F0000000000000ull,
                                   0x7FEFFFFFFFFFFFFFull };
    switch (rnd() % 4) {
    case 0:  return fs[rnd() % 16] | (uint64_t)fs[rnd() % 16] << 32;
    case 1:  return ds[rnd() % (sizeof ds / sizeof ds[0])];
    case 2:  return (uint64_t)(0x3F0u + rnd() % 0x20) << 52 | (uint64_t)rnd() << 20;  /* ordinary doubles */
    default: return (uint64_t)rnd() << 32 | rnd();
    }
}

int main(int argc, char **argv)
{
    int runs = argc > 1 ? atoi(argv[1]) : 100;
    const char *skip = argc > 2 ? argv[2] : "";

    mem = guest_mem_alloc();
    check_uc(uc_open(UC_ARCH_ARM, UC_MODE_ARM, &uc), "open");
    check_uc(uc_ctl_set_cpu_model(uc, UC_CPU_ARM_11MPCORE), "cpu model");   /* the 3DS's CPU */
    check_uc(uc_mem_map(uc, 0, 0x100000000ull, UC_PROT_ALL), "map 4 GiB");   /* same flat space as ours */
    for (int i = 0; i < 16; i++)
        uc_dregs[i] = UC_ARM_REG_D0 + i;
    /* Switch the VFP on: coprocessor access (CPACR cp10/cp11) and FPEXC.EN. */
    uint32_t cpacr = 0x00F00000u, fpexc = 0x40000000u;
    check_uc(uc_reg_write(uc, UC_ARM_REG_C1_C0_2, &cpacr), "cpacr");
    check_uc(uc_reg_write(uc, UC_ARM_REG_FPEXC, &fpexc), "fpexc");
    uc_hook h_code, h_write;
    check_uc(uc_hook_add(uc, &h_code, UC_HOOK_CODE, (void *)on_code, NULL, 1, 0), "code hook");
    check_uc(uc_hook_add(uc, &h_write, UC_HOOK_MEM_WRITE, (void *)on_write, NULL, 1, 0), "write hook");

    uint64_t total_steps = 0;
    int limited = 0, tested = 0;
    for (size_t fi = 0; fi < recomp_nsyms; fi++) {
        const RecompSym *sym = &recomp_syms[fi];
        cur_fn = sym->name;
        /* "+a,b,c" runs only those functions; "a,b,c" skips them. */
        int only = skip[0] == '+';
        const char *list = only ? skip + 1 : skip;
        size_t len = strlen(sym->name);
        const char *hit = strstr(list, sym->name);
        while (hit && !((hit == list || hit[-1] == ',') && (hit[len] == ',' || hit[len] == 0)))
            hit = strstr(hit + 1, sym->name);
        if (only && !hit)
            continue;
        if (!only && hit) {
            printf("SKIP %-12s (takes function pointers)\n", sym->name);
            continue;
        }
        uint64_t fn_steps = 0;
        tested++;

        for (cur_run = 0; cur_run < runs; cur_run++) {
            sync_memory();
            uint32_t r[15];
            for (int i = 0; i < 4; i++)
                r[i] = random_arg();
            for (int i = 4; i < 13; i++)
                r[i] = rnd();
            r[13] = STACK_TOP - 64;     /* room above sp for stack arguments */
            r[14] = RETURN_ADDR;
            uint32_t nzcv = rnd() & 0xF;
            uint64_t d[16];
            for (int i = 0; i < 16; i++)
                d[i] = random_vfp();
            /* Half the runs in IEEE mode, half in libctru's RunFast mode
               (flush-to-zero + default NaN); always round to nearest. */
            uint32_t fpscr = (rnd() & 0xFu) << 28 | (rnd() % 2 ? 0x03000000u : 0);

            Step fin;
            UcEnd end = run_unicorn(sym->addr, r, nzcv, d, fpscr, &fin);
            limited += end != UC_RETURNED;

            Ctx ctx;
            memset(&ctx, 0, sizeof ctx);
            memcpy(ctx.r, r, sizeof r);
            ctx.n = (nzcv >> 3) & 1; ctx.z = (nzcv >> 2) & 1; ctx.c = (nzcv >> 1) & 1; ctx.v = nzcv & 1;
            memcpy(ctx.vfp.x, d, sizeof d);
            ctx.fpscr = fpscr;
            ctx.mem = mem;
            step = nwrites = 0;
            prev_text = NULL;

            int how = setjmp(stop);
            if (how == 0) {
                sym->fn(&ctx);
                /* Returned: Unicorn must have returned too, after the same steps. */
                check_writes_done();
                if (end != UC_RETURNED || step != ref_len) {
                    report_header();
                    printf("    recompiled code returned after %zu instructions; unicorn %s after %zu\n", step,
                           end == UC_RETURNED ? "returned" : end == UC_LIMIT ? "was still running" : "faulted",
                           ref_len);
                    return 1;
                }
                if (!same_state(&ctx, &fin)) {
                    report_header();
                    printf("  (final state after return)\n");
                    report_state(&ctx, &fin);
                    return 1;
                }
            } else if (how == STOP_DIVERGED) {
                printf("  inputs: r0-r3 = %08" PRIx32 " %08" PRIx32 " %08" PRIx32 " %08" PRIx32 ", nzcv = %" PRIx32 "\n",
                       r[0], r[1], r[2], r[3], nzcv);
                return 1;
            } else if (end == UC_RETURNED) {
                /* STOP_LIMIT although Unicorn returned: we ran past its return. */
                report_header();
                printf("    recompiled code kept running after unicorn returned (%zu instructions)\n", ref_len);
                return 1;
            }
            fn_steps += step;
        }
        printf("PASS %-12s %3d runs %8" PRIu64 " instructions compared\n", sym->name, runs, fn_steps);
        total_steps += fn_steps;
    }

    printf("all %d functions match unicorn: %" PRIu64 " instructions compared, %d runs hit the %d-instruction limit\n",
           tested, total_steps, limited, LIMIT);
    uc_close(uc);
    guest_mem_free(mem);
    return 0;
}
